import { describe, expect, it } from "vite-plus/test";

import { tokenizeCliArgs } from "./cliArgs.ts";

describe("heimdall bench tokenizer", () => {
  it("keeps a no-break space inside a path", () => {
    const path = "/tmp/project\u00a0name";
    expect(tokenizeCliArgs(`--add-dir ${path} --verbose`)).toEqual(["--add-dir", path, "--verbose"]);
  });
});

